    scanf("%100000s %100000s", a, b);
    int count[26] = {0};
    for (int i = 0; a[i]; i++) {
        count[a[i] - 'a']++;
    }
    for (int i = 0; b[i]; i++) {
        count[b[i] - 'a']--;
    }
    int same = 1;
    for (int k = 0; k < 26; k++) {
        if (count[k] != 0) {
            same = 0;
            break;
        }
    }
    printf("%s\n", same ? "да" : "нет");
    return 0;
}

