#include <stdio.h>

int main(void) {
    static int a[100][100];
    int n, m;
    scanf("%d %d", &n, &m);
    for (int r = 0; r < n; r++) {
        for (int c = 0; c < m; c++) {
            scanf("%d", &a[r][c]);
        }
    }
    int top = 0, bottom = n - 1, left = 0, right = m - 1;
    int printed = 0;
    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; c++) {
            printf(printed++ ? " %d" : "%d", a[top][c]);
        }
        top++;
        for (int r = top; r <= bottom; r++) {
            printf(printed++ ? " %d" : "%d", a[r][right]);
        }
        right--;
        if (top <= bottom) {
            for (int c = right; c >= left; c--) {
                printf(printed++ ? " %d" : "%d", a[bottom][c]);
            }
            bottom--;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; r--) {
                printf(printed++ ? " %d" : "%d", a[r][left]);
            }
            left++;
        }
    }
    printf("\n");
    return 0;
}

