#include <stdio.h>
#include <ctype.h>

int main(void) {
    int count[26] = {0};
    int c;
    while ((c = getchar()) != EOF) {
        if (isalpha(c)) {
            count[tolower(c) - 'a']++;
        }
    }
    int best = 0;
    for (int k = 1; k < 26; k++) {
        if (count[k] > count[best]) {
            best = k;
        }
    }
    printf("%c %d\n", 'a' + best, count[best]);
    return 0;
}

